import { createRequire } from 'node:module'
import { join } from 'node:path'
import { mkdirSync, readFileSync } from 'node:fs'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
mkdirSync(out, { recursive: true })

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const errors = []
try {
  const page = await browser.newPage({ viewport: { width: 1100, height: 700 } })
  page.setDefaultTimeout(30000)
  page.on('pageerror', e => errors.push('pageerror: ' + e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()) })

  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__apex && window.__apex.state.mode === 'title')
  await page.click('#startBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 9000 })
  console.log('visibility:', await page.evaluate(() => document.visibilityState))

  // Seed a close-to-line final lap, then drive across the line.
  await page.evaluate(() => {
    const a = window.__apex
    const car = a.playerCar
    const slot = a.track.gridSlot(180, 0)
    car.pos.x = slot.x
    car.pos.y = slot.y
    car.angle = slot.angle
    car.vel.x = 0
    car.vel.y = 0
    car.speed = 0
    car.prevIndex = slot.index
    car.progIndex = slot.index
    car.prog = a.track.N * 2
    car.laps = 2
    car.lapStart = 30
    car.lapTimes = [31.2, 30.8]
    car.bestLap = 30.8
    car.topSpeed = 312
    a.state.raceTime = 66
  })
  // Push the car forward across the line over successive frames.
  await page.evaluate(() => {
    const a = window.__apex
    const track = a.track
    let idx = 470, step = 0
    window.__push = setInterval(() => {
      const car = a.playerCar
      const p = track.points[idx % track.N]
      const n = track.normals[idx % track.N]
      car.pos.x = p.x - n.x * 30
      car.pos.y = p.y - n.y * 30
      car.angle = Math.atan2(track.tangents[idx % track.N].y, track.tangents[idx % track.N].x)
      car.vel.x = 0
      car.vel.y = 0
      idx++
      step++
      if (step > 30) clearInterval(window.__push)
    }, 120)
  })

  let final = null
  const t0 = Date.now()
  while (Date.now() - t0 < 150000) {
    await page.waitForTimeout(500)
    final = await page.evaluate(() => {
      const a = window.__apex
      return {
        mode: a.state.mode,
        resultsTimer: Math.round(a.state.resultsTimer * 100) / 100,
        laps: a.playerCar.laps,
        finished: a.playerCar.finished,
        resultsVisible: !document.getElementById('resultsScreen').classList.contains('hidden'),
        resultTitle: document.getElementById('resultTitle').textContent,
        resultTotal: document.getElementById('resultTotal').textContent,
        rows: document.querySelectorAll('#resultRows tr').length,
      }
    })
    if (final.resultsVisible) break
  }
  console.log('FINAL', JSON.stringify(final))
  await page.screenshot({ path: join(out, 'check-results.jpg'), type: 'jpeg', quality: 72 })

  if (final.resultsVisible) {
    await page.click('#againBtn')
    await page.waitForTimeout(600)
    console.log('AFTER AGAIN', await page.evaluate(() => ({
      mode: window.__apex.state.mode,
      titleHidden: document.getElementById('titleScreen').classList.contains('hidden'),
      resultsHidden: document.getElementById('resultsScreen').classList.contains('hidden'),
    })))
  }
  console.log('ERRORS', errors.length ? JSON.stringify(errors) : 'none')
} finally {
  await browser.close()
}

