const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
try {
  const page = await browser.newPage({ viewport: { width: 1100, height: 700 } })
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__apex)
  await page.click('#startBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 9000 })
  const cdp = await page.context().newCDPSession(page)
  await cdp.send('Profiler.enable')
  await cdp.send('Profiler.setSamplingInterval', { interval: 500 })
  await cdp.send('Profiler.start')
  await page.waitForTimeout(6000)
  const { profile } = await cdp.send('Profiler.stop')
  const byId = new Map(profile.nodes.map(n => [n.id, n]))
  const counts = new Map()
  for (const id of profile.samples || []) {
    const n = byId.get(id)
    if (!n) continue
    const f = n.callFrame
    const key = `${f.functionName || '(anon)'} @ ${f.url.split('/').slice(-1)[0]}:${f.lineNumber + 1}`
    counts.set(key, (counts.get(key) || 0) + 1)
  }
  const total = [...counts.values()].reduce((a, b) => a + b, 0)
  const top = [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 20)
  console.log('samples', total)
  for (const [k, v] of top) console.log((100 * v / total).toFixed(1) + '%', k)
} finally { await browser.close() }

