import { createRequire } from 'node:module'
import { join } from 'node:path'
import { mkdirSync, readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
mkdirSync(out, { recursive: true })

const autopilot = () => {
  const a = window.__apex
  const track = a.track
  const N = track.N
  const held = new Set()
  function setKey(code, on) {
    if (on && !held.has(code)) { held.add(code); window.dispatchEvent(new KeyboardEvent('keydown', { code, bubbles: true })) }
    else if (!on && held.has(code)) { held.delete(code); window.dispatchEvent(new KeyboardEvent('keyup', { code, bubbles: true })) }
  }
  window.__auto = setInterval(() => {
    const car = a.playerCar
    if (a.state.mode !== 'racing') {
      setKey('KeyW', false); setKey('KeyS', false); setKey('KeyA', false); setKey('KeyD', false)
      return
    }
    const i = car.prevIndex
    const look = Math.max(9, Math.min(46, Math.round((72 + car.speed * 0.5) / track.ds)))
    const p = track.points[(i + look) % N]
    const desired = Math.atan2(p.y - car.pos.y, p.x - car.pos.x)
    let diff = desired - car.angle
    while (diff > Math.PI) diff -= Math.PI * 2
    while (diff < -Math.PI) diff += Math.PI * 2
    const steer = Math.max(-1, Math.min(1, diff * 2.45))
    const target = track.speedProfile[(i + 16) % N] * 0.97
    setKey('KeyA', steer < -0.12)
    setKey('KeyD', steer > 0.12)
    setKey('KeyW', car.speed < target * 0.99)
    setKey('KeyS', car.speed > target * 1.06)
  }, 30)
}

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const errors = []
try {
  const page = await browser.newPage({ viewport: { width: 1000, height: 640 } })
  page.on('pageerror', e => errors.push('pageerror: ' + e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()) })
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__apex && window.__apex.state.mode === 'title')
  await page.waitForTimeout(500)
  await page.screenshot({ path: join(out, 'final-title.jpg'), type: 'jpeg', quality: 72 })

  await page.click('#startBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 9000 })
  await page.evaluate(autopilot)
  await page.waitForTimeout(6000)
  const race = await page.evaluate(() => {
    const a = window.__apex
    const q = s => document.querySelector(s)
    return {
      mode: a.state.mode,
      speed: Math.round(a.playerCar.kmh),
      laps: a.playerCar.laps + 1,
      lapTime: q('#lapTime').textContent,
      pos: q('#posNow').textContent,
      gaugeText: null,
      miniHash: document.getElementById('minimap').toDataURL().length,
    }
  })
  console.log('RACE', JSON.stringify(race))
  await page.screenshot({ path: join(out, 'final-race.jpg'), type: 'jpeg', quality: 72 })

  await page.keyboard.press('KeyP')
  await page.waitForTimeout(300)
  console.log('PAUSE', await page.evaluate(() => ({
    mode: window.__apex.state.mode,
    visible: !document.getElementById('pauseScreen').classList.contains('hidden'),
  })))
  await page.screenshot({ path: join(out, 'final-pause.jpg'), type: 'jpeg', quality: 72 })
  await page.click('#resumeBtn')
  await page.waitForTimeout(300)
  console.log('RESUME', await page.evaluate(() => window.__apex.state.mode))
  await page.evaluate(() => clearInterval(window.__auto))

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true })
  mobile.on('pageerror', e => errors.push('mobile pageerror: ' + e.message))
  mobile.on('console', m => { if (m.type() === 'error') errors.push('mobile console: ' + m.text()) })
  await mobile.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await mobile.waitForFunction(() => window.__apex && window.__apex.state.mode === 'title')
  await mobile.waitForTimeout(400)
  await mobile.screenshot({ path: join(out, 'final-mobile-title.jpg'), type: 'jpeg', quality: 72 })
  await mobile.click('#startBtn')
  await mobile.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  await mobile.locator('[data-act="throttle"]').dispatchEvent('pointerdown', { pointerId: 1 })
  await mobile.waitForTimeout(2500)
  const mobileState = await mobile.evaluate(() => ({ mode: window.__apex.state.mode, speed: Math.round(window.__apex.playerCar.kmh) }))
  await mobile.locator('[data-act="throttle"]').dispatchEvent('pointerup', { pointerId: 1 })
  await mobile.screenshot({ path: join(out, 'final-mobile-race.jpg'), type: 'jpeg', quality: 72 })
  console.log('MOBILE', JSON.stringify(mobileState))
  await mobile.close()

  console.log('ERRORS', errors.length ? JSON.stringify(errors) : 'none')
} finally { await browser.close() }

